"""Auto-generated interceptor verification for Minecraft TCG. See /test-interceptors.

Generated by /ng-plus iter 1 polish pass on Minecraft.

Catches the "depths trap": interceptor is wired but effect_fn returns [] silently.
Each test manually invokes the callback and asserts at least one Event of the
expected category is returned.

Event-type mapping used:
  - material gain  → EventType.MC_MATERIAL_GAIN
  - draw           → EventType.DRAW
  - damage         → EventType.DAMAGE
  - life/heal      → EventType.LIFE_CHANGE
  - token create   → EventType.CREATE_TOKEN
  - zone change    → EventType.ZONE_CHANGE  (opp discard / mill)
  - destroy        → EventType.OBJECT_DESTROYED
  - untap          → EventType.UNTAP
  - explore biome  → EventType.MC_EXPLORE_BIOME
"""

import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from src.engine.types import CardType, Event, EventType, GameState, ZoneType
from src.engine.game import Game
from src.cards.minecraft import MINECRAFT_CARDS


# ---------------------------------------------------------------------------
# Cards whose effects can't be auto-tested — one-line reason each.
# ---------------------------------------------------------------------------

