# ---------------------------------------------------------------------------
# Scaffold helpers — mirrored from test_minecraft_tcg.py patterns
# ---------------------------------------------------------------------------

def _build_game():
    """Minimal 2-player Minecraft game with both players set up."""
    game = Game(mode="minecraft")
    p1 = game.add_player("P1")
    p2 = game.add_player("P2")
    game.setup_minecraft_player(p1, [])
    game.setup_minecraft_player(p2, [])
    return game, p1, p2


def _place_on_battlefield(game, player_id, card_def):
    """Create a GameObject for card_def in BATTLEFIELD owned by player_id."""
    obj = game.create_object(
        name=card_def.name,
        owner_id=player_id,
        zone=ZoneType.BATTLEFIELD,
        characteristics=card_def.characteristics,
        card_def=card_def,
    )
    obj.controller = player_id
    return obj


def _place_in_hand(game, player_id, card_def):
    obj = game.create_object(
        name=card_def.name,
        owner_id=player_id,
        zone=ZoneType.HAND,
        characteristics=card_def.characteristics,
        card_def=card_def,
    )
    obj.controller = player_id
    return obj


def _place_in_library(game, player_id, card_def):
    obj = game.create_object(
        name=card_def.name,
        owner_id=player_id,
        zone=ZoneType.LIBRARY,
        characteristics=card_def.characteristics,
        card_def=card_def,
    )
    obj.controller = player_id
    return obj


def _place_in_graveyard(game, player_id, card_def):
    obj = game.create_object(
        name=card_def.name,
        owner_id=player_id,
        zone=ZoneType.GRAVEYARD,
        characteristics=card_def.characteristics,
        card_def=card_def,
    )
    obj.controller = player_id
    return obj


def _add_to_hand_zone(game, player_id, obj):
    """Move obj to a player's hand zone (for discard-trigger testing)."""
    zone = game.state.zones.get(f"hand_{player_id}")
    if zone and obj.id not in zone.objects:
        zone.objects.append(obj.id)


def _add_to_library_zone(game, player_id, obj):
    zone = game.state.zones.get(f"library_{player_id}")
    if zone and obj.id not in zone.objects:
        zone.objects.append(obj.id)


