def test_card_chop_trees_on_play():
    """Chop Trees: on_play — expects MC_MATERIAL_GAIN (2 wood)."""
    game, p1, p2 = _build_game()
    card = _place_on_battlefield(game, p1.id, MINECRAFT_CARDS["Chop Trees"])
    fn = MINECRAFT_CARDS["Chop Trees"].mc_on_play
    events = fn(card, game.state, target_id=None)
    assert len(events) > 0, "Chop Trees on_play returned no events"
    assert any(e.type == EventType.MC_MATERIAL_GAIN for e in events), \
        f"Expected MC_MATERIAL_GAIN, got {[e.type for e in events]}"


