    game, p1, p2 = _build_game()
    block = _place_on_battlefield(game, p2.id, MINECRAFT_CARDS["Oak Planks"])
    block.state.mc_grid_x = 0
    block.state.mc_grid_y = 0
    game.state.minecraft_grid[p2.id][0][0] = block.id
    card = _place_on_battlefield(game, p1.id, MINECRAFT_CARDS["Entity 303"])
    fn = MINECRAFT_CARDS["Entity 303"].mc_on_play
    events = fn(card, game.state, target_id=None)
    assert len(events) > 0, "Entity 303 on_play returned no events with opp grid object"
    assert any(e.type == EventType.DAMAGE for e in events), \
        f"Expected DAMAGE, got {[e.type for e in events]}"


