# ---------------------------------------------------------------------------
# Entry point — run all tests and summarise
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    import traceback

    tests = [(k, v) for k, v in sorted(globals().items()) if k.startswith("test_") and callable(v)]
    passed, failed, errors = [], [], []
    for name, fn in tests:
        try:
            fn()
            passed.append(name)
        except AssertionError as exc:
            failed.append((name, str(exc)))
        except Exception as exc:
            errors.append((name, f"{type(exc).__name__}: {exc}"))

    print(f"\n=== Interceptor verification: minecraft ===")
    print(f"  passed:  {len(passed)}")
    print(f"  failed:  {len(failed)}")
    print(f"  errors:  {len(errors)}")
    print(f"  skipped: {len(SKIPPED_CARDS)} (see SKIPPED_CARDS dict at top of file)")
    total_run = len(passed) + len(failed) + len(errors)
    if total_run:
        rate = len(passed) / total_run * 100
        print(f"  pass rate: {rate:.1f}% (over {total_run} runnable tests)")
    if failed:
        print("\n--- FAILURES (first 30) ---")
        for n, msg in failed[:30]:
            print(f"  {n}: {msg}")
    if errors:
        print("\n--- ERRORS (first 30) ---")
        for n, msg in errors[:30]:
            print(f"  {n}: {msg}")
    sys.exit(0 if not failed and not errors else 1)
